import React, { useRef, useEffect } from 'react';
import IframeContent from './IframeContent';

const App = () => {
  const iframeRef = useRef(null);

  useEffect(() => {
    if (iframeRef.current) {
      const iframeDoc = iframeRef.current.contentWindow.document;
      const rootNode = document.createElement('div');
      iframeDoc.body.appendChild(rootNode);

      // Import Tailwind CSS inside the iframe
      const tailwindLink = document.createElement('link');
      tailwindLink.href = process.env.PUBLIC_URL + '/tailwind.css';
      tailwindLink.rel = 'stylesheet';
      iframeDoc.head.appendChild(tailwindLink);

      ReactDOM.render(<IframeContent />, rootNode);
    }
  }, []);

  return (
    <div className="p-4">
      <h1 className="text-4xl font-bold mb-4">React App with Iframe</h1>
      <iframe className="w-full h-screen" ref={iframeRef} title="Figma Iframe"></iframe>
    </div>
  );
};

